 "content": "def transform(grid):
    """Restore cells masked with 2 using the grid's horizontal/vertical mirror symmetry."""
    h, w = len(grid), len(grid[0])
    if any(len(row) != w for row in grid):
        raise ValueError("grid must be rectangular")
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            candidates = [
                grid[h - 1 - r][c],
                grid[r][w - 1 - c],
                grid[h - 1 - r][w - 1 - c],
            ]
            values = [v for v in candidates if v != 2]
            if not values:
                raise ValueError(f"cannot infer masked cell at {(r, c)}")
            # The original picture is mirror-symmetric; all visible mirrored
            # counterparts agree. Keep a deterministic fallback for a masked mate.
            out[r][c] = max(set(values), key=values.count)
    return out
